const {chromium}=require('/Users/ph.qian/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const fs=require('node:fs/promises'),assert=require('node:assert/strict');
const text=n=>(n.text||'')+(n.content||[]).map(text).join('');
(async()=>{const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const results=[];try{const p=await b.newPage();await p.goto(process.env.VDOC_TEST_URL||'http://localhost:5173/');await p.getByRole('button',{name:'New document',exact:true}).click();const body=p.getByRole('textbox',{name:'Document body',exact:true});await body.fill('First');await p.keyboard.press('Enter');await p.keyboard.type('Second');await p.waitForTimeout(700);for(const afterMenu of [false,true]){if(afterMenu){await p.keyboard.press('Meta+a');await p.getByRole('button',{name:'Bulleted list',exact:true}).click();await p.waitForTimeout(250);await body.locator('li p').filter({hasText:'Second'}).click();}for(let n=0;n<6;n++){await p.keyboard.press('Shift+ArrowLeft');console.log('select',afterMenu,n,JSON.stringify(await p.evaluate(()=>({selection:window.vdoc.snapshot().selection,dom:getSelection()?.toString(),active:document.activeElement?.getAttribute('aria-label')}))));}await p.waitForFunction(()=>{const s=window.vdoc.snapshot().selection;return s.to-s.from===6});const before=await p.evaluate(()=>window.vdoc.snapshot().document);if(afterMenu){await p.getByRole('button',{name:'Format',exact:true}).click();await p.getByRole('menuitem',{name:'Increase indent',exact:true}).click();await p.waitForTimeout(700);}const historyBefore=await p.evaluate(()=>window.vdoc.snapshot().document);const selection=await p.evaluate(()=>window.vdoc.snapshot().selection);await p.keyboard.press('ArrowRight');await p.keyboard.press('Enter');await p.waitForTimeout(100);const after=await p.evaluate(()=>window.vdoc.snapshot().document);assert.equal(text(after),text(before),'Rapid collapse + Enter must preserve existing text');console.log('retained',afterMenu,text(after));results.push({afterMenu,selectedLength:selection.to-selection.from,before,after});await p.getByRole('button',{name:'Undo · ⌘Z',exact:true}).click();await p.waitForTimeout(100);assert.deepEqual(await p.evaluate(()=>window.vdoc.snapshot().document),historyBefore,'Undo restores exact text and structure');}await fs.writeFile((process.env.VDOC_EVIDENCE_DIR||'tests/fixtures/combined-workflow-20261010')+'/rapid-selection.json',JSON.stringify({browser:b.version(),input:'Real keyboard Shift+ArrowLeft, ArrowRight and immediate Enter; no DOM selection injection',results},null,2));console.log('Rapid real-keyboard selection collapse and Enter retain text, with and without a formatting menu.');}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1});
